class TaskTemplate extends DataClass implements Insertable<TaskTemplate> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Set when the item goes to the Trash; "Delete forever" removes the row.
  final DateTime? deletedAt;
  final String name;
  final String title;
  final String content;
  final TaskKind kind;

  /// Checklist items, one per line.
  final String items;

  /// Tag ids, comma separated.
  final String tagIds;
  final int sortOrder;
  const TaskTemplate({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.name,
    required this.title,
    required this.content,
    required this.kind,
    required this.items,
    required this.tagIds,
    required this.sortOrder,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['name'] = Variable<String>(name);
    map['title'] = Variable<String>(title);
    map['content'] = Variable<String>(content);
    {
      map['kind'] = Variable<String>(
        $TemplatesTable.$converterkind.toSql(kind),
      );
    }
    map['items'] = Variable<String>(items);
    map['tag_ids'] = Variable<String>(tagIds);
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

  TemplatesCompanion toCompanion(bool nullToAbsent) {
    return TemplatesCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      name: Value(name),
      title: Value(title),
      content: Value(content),
      kind: Value(kind),
      items: Value(items),
      tagIds: Value(tagIds),
      sortOrder: Value(sortOrder),
    );
  }

  factory TaskTemplate.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return TaskTemplate(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      name: serializer.fromJson<String>(json['name']),
      title: serializer.fromJson<String>(json['title']),
      content: serializer.fromJson<String>(json['content']),
      kind: serializer.fromJson<TaskKind>(json['kind']),
      items: serializer.fromJson<String>(json['items']),
      tagIds: serializer.fromJson<String>(json['tagIds']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
    );
  }
  @override
