class Countdown extends DataClass implements Insertable<Countdown> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Set when the item goes to the Trash; "Delete forever" removes the row.
  final DateTime? deletedAt;
  final String name;
  final DateTime date;
  final CountdownType type;
  final CountMode countMode;
  final bool ignoreYear;
  final bool showAge;
  final String reminders;
  final String? repeatRule;
  final CountdownVisibility visibility;

  /// Card layout (0-5) and color (hex).
  final int style;
  final String? color;
  final String note;
  final DateTime? pinnedAt;
  final DateTime? archivedAt;
  final int sortOrder;

  /// Emoji or text shown before the name, and the background picture's file name,
  /// schema v12.
  final String? icon;

  /// Background of a "Texto" icon (one letter on a colored circle), `#RRGGBB`.
  final String? iconColor;
  final String? image;

  /// "Modo de Contagem": Cronômetro counts up from the date instead of down to the
  /// next occurrence (schema v14).
  final bool countUp;

  /// The project it counts down to (schema v20): a list or a folder, for its dashboard.
  final String? listId;
  final String? folderId;

  /// When the project was closed (or its day came), and its final report frozen then as JSON.
  final DateTime? closedAt;
  final String? report;
  const Countdown({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.name,
    required this.date,
    required this.type,
    required this.countMode,
    required this.ignoreYear,
    required this.showAge,
    required this.reminders,
    this.repeatRule,
    required this.visibility,
    required this.style,
    this.color,
    required this.note,
    this.pinnedAt,
    this.archivedAt,
    required this.sortOrder,
    this.icon,
    this.iconColor,
    this.image,
    required this.countUp,
    this.listId,
    this.folderId,
    this.closedAt,
    this.report,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['name'] = Variable<String>(name);
    map['date'] = Variable<DateTime>(date);
    {
      map['type'] = Variable<String>(
        $CountdownsTable.$convertertype.toSql(type),
      );
    }
    {
      map['count_mode'] = Variable<String>(
        $CountdownsTable.$convertercountMode.toSql(countMode),
      );
    }
    map['ignore_year'] = Variable<bool>(ignoreYear);
    map['show_age'] = Variable<bool>(showAge);
    map['reminders'] = Variable<String>(reminders);
    if (!nullToAbsent || repeatRule != null) {
      map['repeat_rule'] = Variable<String>(repeatRule);
    }
    {
      map['visibility'] = Variable<String>(
        $CountdownsTable.$convertervisibility.toSql(visibility),
      );
    }
    map['style'] = Variable<int>(style);
    if (!nullToAbsent || color != null) {
      map['color'] = Variable<String>(color);
    }
    map['note'] = Variable<String>(note);
    if (!nullToAbsent || pinnedAt != null) {
      map['pinned_at'] = Variable<DateTime>(pinnedAt);
    }
    if (!nullToAbsent || archivedAt != null) {
      map['archived_at'] = Variable<DateTime>(archivedAt);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    if (!nullToAbsent || icon != null) {
      map['icon'] = Variable<String>(icon);
    }
    if (!nullToAbsent || iconColor != null) {
      map['icon_color'] = Variable<String>(iconColor);
    }
    if (!nullToAbsent || image != null) {
      map['image'] = Variable<String>(image);
    }
    map['count_up'] = Variable<bool>(countUp);
    if (!nullToAbsent || listId != null) {
      map['list_id'] = Variable<String>(listId);
    }
    if (!nullToAbsent || folderId != null) {
      map['folder_id'] = Variable<String>(folderId);
    }
    if (!nullToAbsent || closedAt != null) {
      map['closed_at'] = Variable<DateTime>(closedAt);
    }
    if (!nullToAbsent || report != null) {
      map['report'] = Variable<String>(report);
    }
    return map;
  }

  CountdownsCompanion toCompanion(bool nullToAbsent) {
    return CountdownsCompanion(
      id: Value(id),
