class FinEntry extends DataClass implements Insertable<FinEntry> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Set when the item goes to the Trash; "Delete forever" removes the row.
  final DateTime? deletedAt;
  final FinKind kind;
  final int amount;
  final DateTime date;
  final String description;
  final String? categoryId;
  final String? cardId;
  final DateTime? invoiceMonth;
  final String? installmentGroup;
  final int? installmentIndex;
  final int? installmentCount;

  /// The recurring bill it paid, and which occurrence (its due day).
  final String? recurringId;
  final DateTime? recurringDue;
  final String note;
  const FinEntry({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.kind,
    required this.amount,
    required this.date,
    required this.description,
    this.categoryId,
    this.cardId,
    this.invoiceMonth,
    this.installmentGroup,
    this.installmentIndex,
    this.installmentCount,
    this.recurringId,
    this.recurringDue,
    required this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    {
      map['kind'] = Variable<String>(
        $FinEntriesTable.$converterkind.toSql(kind),
      );
    }
