class DietEntry extends DataClass implements Insertable<DietEntry> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Set when the item goes to the Trash; "Delete forever" removes the row.
  final DateTime? deletedAt;
  final DateTime day;
  final String meal;

  /// "taco:1" or a [DietFoods] id.
  final String foodId;
  final String name;
  final double quantity;
  final String? measureName;
  final double grams;
  final double? kcal;
  final double? protein;
  final double? carbs;
  final double? fat;
  final double? fiber;
  final int sortOrder;

  /// The plan item this entry came from ("Importar plano do dia"), for the adherence (schema v20).
  final String? planItemId;
  const DietEntry({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.day,
    required this.meal,
    required this.foodId,
    required this.name,
    required this.quantity,
    this.measureName,
    required this.grams,
    this.kcal,
    this.protein,
    this.carbs,
    this.fat,
    this.fiber,
    required this.sortOrder,
    this.planItemId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['day'] = Variable<DateTime>(day);
    map['meal'] = Variable<String>(meal);
    map['food_id'] = Variable<String>(foodId);
    map['name'] = Variable<String>(name);
    map['quantity'] = Variable<double>(quantity);
    if (!nullToAbsent || measureName != null) {
      map['measure_name'] = Variable<String>(measureName);
    }
    map['grams'] = Variable<double>(grams);
    if (!nullToAbsent || kcal != null) {
      map['kcal'] = Variable<double>(kcal);
    }
    if (!nullToAbsent || protein != null) {
      map['protein'] = Variable<double>(protein);
    }
    if (!nullToAbsent || carbs != null) {
      map['carbs'] = Variable<double>(carbs);
    }
    if (!nullToAbsent || fat != null) {
      map['fat'] = Variable<double>(fat);
    }
    if (!nullToAbsent || fiber != null) {
      map['fiber'] = Variable<double>(fiber);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    if (!nullToAbsent || planItemId != null) {
      map['plan_item_id'] = Variable<String>(planItemId);
    }
    return map;
  }

